scenario.en:
type Event =
  | { type: "click"; x: number }
  | { type: "key"; code: string }
  | { type: "scroll"; dy: number };  // newly added
function handle(e: Event) {
  switch (e.type) {
    case "click": return e.x;
    case "key": return e.code;
    default: return assertNever(e);
  }
}

